}) {
  if (errorMessage == null || errorMessage.isEmpty) return null;
  if (errorMessage.contains(connectWatchdogTag)) {
    return ProviderStallEvent(
      kind: ProviderStallKind.connectStall,
      message: errorMessage,
      eventsSeen: null,
