final _retryAfterPattern = RegExp(
  r'(?:retry.?after|try again in)[:\s]*(\d+)\s*(s|sec|seconds|m|min|minutes)?',
  caseSensitive: false,
);
void probe(String text) {
  final m = _retryAfterPattern.firstMatch(text);
  if (m == null) { print('$text => NO MATCH'); return; }
  final seconds = m.group(1);
  final unit = m.group(2);
  final wait = seconds == null
      ? ''
      : ' — retry after ~$seconds${unit != null && unit.startsWith('m') ? 'm' : 's'}';
  print('$text => "$wait"');
}
void main() {
  probe('429: rate limit exceeded — retry after 12 seconds');
  probe('429: too many requests, try again in 30s');
  probe('429: quota exhausted, please retry after 2 minutes');
  probe('429: daily quota reached. try again in 23h');
  probe('Rate limited: retry after 1h');
  probe('429: rate limit window, retry-after: 3600');
  probe('429: too many requests');
}
EOF
